const { useState } = React;

function NameForm() {
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const fullName = (firstName + ' ' + lastName).trim();

  return (
    <main>
      <input value={firstName} onChange={(event) => setFirstName(event.currentTarget.value)} placeholder="이름" />
      <input value={lastName} onChange={(event) => setLastName(event.currentTarget.value)} placeholder="성" />
      <p>{fullName || '이름을 입력하세요'}</p>
    </main>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<NameForm />);

